'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let P, id='demo', token, assets=[], projects=[], sdk='', page='home', sceneIndex=0, eventIndex=0, dirty=false, saving=false, saveTimer, selectedObject=0, graph=false, undoStack=[],redoStack=[], changeSerial=0;
const tabs=[['home','◈','Обзор'],['story','▤','Сценарий'],['characters','♙','Персонажи'],['assets','▧','Ресурсы'],['art','✧','Фоны и спрайты'],['cinema','▷','Видео и титры'],['interface','▣','Интерфейс'],['minigames','◇','Мини-игры'],['steam','☆','Steam и Python'],['export','↗','Экспорт'],['help','?','Руководство']];
const names={say:'Реплика',background:'Фон',show:'Показать героя',hide:'Скрыть героя',music:'Музыка',sound:'Звук',stop_music:'Остановить музыку',choice:'Выбор',jump:'Переход',condition:'Условие',set:'Изменить переменную',day:'День',ending:'Концовка',video:'Видео',cutscene:'Катсцена',credits:'Титры',minigame:'Мини-игра',python:'Python модуль',achievement:'Достижение',pause:'Пауза',effect:'Эффект'};
const effects=[['dissolve','Плавное появление'],['fade','Затемнение'],['hpunch','Встряска по горизонтали'],['vpunch','Встряска по вертикали'],['none','Без эффекта']];
function field(label,name,value,type='text',extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`}
function area(label,name,value){return `<label class="field">${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function sel(label,name,value,options){return `<label class="field">${label}<select name="${name}">${options.map(o=>{let [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`}
function check(label,name,value){return `<label class="field"><span><input type="checkbox" name="${name}" ${value?'checked':''}> ${label}</span></label>`}
function button(label,act,cls=''){return `<button class="${cls}" data-act="${act}">${label}</button>`}
function heading(title,sub,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="row">${actions}</div></div>`}
function charOptions(){return [['','Рассказчик'],...P.characters.map(c=>[c.id,c.name])]}function sceneOptions(){return P.scenes.map(s=>[s.id,s.name])}function assetOptions(ext){return [['','Не выбрано'],...assets.filter(a=>!ext||ext.test(a.name)).map(a=>[a.name,a.name])]}function varOptions(){return [['','Не сохранять'],...P.variables.map(v=>v.id)]}
function assetURL(name){return '/asset/'+id+'/'+encodeURIComponent(name)}
async function api(route,data){let r=await fetch('/api/'+route,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-NovelForge-Token':token}:{},body:data?JSON.stringify({id,...data}):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||r.statusText);return j}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6000)}
function snapshot(){undoStack.push(JSON.stringify(P));if(undoStack.length>70)undoStack.shift();redoStack=[]}
function changed(){dirty=true;changeSerial++;$('#savestate')&&($('#savestate').textContent='Есть изменения');clearTimeout(saveTimer);saveTimer=setTimeout(()=>save().catch(e=>toast(e.message)),1000)}
async function save(){if(saving){await new Promise(r=>setTimeout(r,100));return save()}if(!dirty)return;clearTimeout(saveTimer);saving=true;const serial=changeSerial;try{let r=await api('save',{project:JSON.parse(JSON.stringify(P)),revision:P.revision});P.revision=r.project.revision;let listed=projects.find(x=>x.id===id);if(listed)listed.title=P.title;if(serial===changeSerial)dirty=false;$('#savestate')&&($('#savestate').textContent=dirty?'Есть изменения':'Сохранено на компьютере');}finally{saving=false}if(dirty)return save()}
async function openProject(newid){if(typeof importSource!=='undefined'&&importSource.dirty&&!confirm('Отбросить несохраненные правки исходника?'))return;await save();if(id!==newid&&typeof importSource!=='undefined'){importSource={file:'',text:'',digest:'',dirty:false};if(typeof art!=='undefined')art.assignCharacter=''}id=newid;let r=await api('project/'+id);P=r.project;P.artboards=P.artboards||[];assets=r.assets;sceneIndex=0;eventIndex=0;undoStack=[];redoStack=[];localStorage.setItem('nf-project',id);render()}
function render(){let title=tabs.find(t=>t[0]===page)?.[2]||'';$('#app').innerHTML=`<div class="layout"><aside><div class="brand"><img src="/stock/novelforge_logo.png" alt="Логотип NovelForge">NovelForge</div><small style="padding-left:8px">СТУДИЯ ВИЗУАЛЬНЫХ НОВЕЛЛ</small><nav class="nav">${tabs.map(([k,i,n])=>`<button data-page="${k}" class="${page===k?'active':''}"><span>${i}</span>${n}</button>`).join('')}</nav><div class="asidefoot">Локальная студия · 1.4<br>Ren’Py 7.4+ / 8.x<br><span class="ok">● Без облака и подписки</span></div></aside><main><header class="topbar"><select id="project-select">${projects.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.title)}</option>`).join('')}</select><div class="row"><span id="savestate" class="save-state">${dirty?'Есть изменения':'Сохранено на компьютере'}</span>${button('↶','undo')}${button('↷','redo')}${button('▷ Предпросмотр','preview')}${button('Экспорт ↗','goto-export','primary')}</div></header><section class="content" id="content"></section></main></div>`;
  $('#content').innerHTML=({home:homeView,story:storyView,characters:charactersView,assets:assetsView,art:artView,cinema:cinemaView,interface:interfaceView,minigames:minigamesView,steam:steamView,export:exportView,imports:importView,audio:audioView,builder:builderView,graphics:graphicsView,music:musicView,help:helpView}[page])();
  bind();if(page==='art')drawArt();if(page==='interface')bindStageDrag();}
function homeView(){let total=P.scenes.reduce((n,s)=>n+s.events.length,0);return heading('История начинается здесь','Соберите мир, героев и события. Код Ren’Py студия подготовит сама.',button('＋ Новый проект','new'))+`<div class="banner"><span class="tag">ВАШ ПРОЕКТ</span><h2 style="margin-top:12px">${esc(P.title)}</h2><p>От первого диалога до собственной игры. Все редакторы связаны одним проектом.</p><div class="row">${button('Открыть сценарий →','goto-story','primary')}${button('Импортировать Word','import-word')}<a class="btn" href="/download/${id}/template">Скачать шаблон Word</a></div></div><div class="grid">${[['Сцены',P.scenes.length],['События',total],['Персонажи',P.characters.length]].map(([t,v])=>`<div class="card"><p>${t}</p><div class="stat">${v}</div></div>`).join('')}</div><div class="grid two" style="margin-top:20px"><div class="card"><h2>Параметры истории</h2><div id="projectform">${field('Название','title',P.title)}${sel('Первая сцена','start',P.start,sceneOptions())}${sel('Совместимость экспорта','target',P.target,[['8','Ren’Py 8.x'],['7','Ren’Py 7.4+ — совместимый синтаксис']])}</div></div><div class="card"><h2>Перенос проекта</h2><p class="help">Резервная копия содержит сценарий и загруженные ресурсы. Ее можно открыть на другом компьютере.</p><div class="row"><a class="btn" data-download="backup" href="/download/${id}/backup">Скачать проект ZIP</a>${button('Открыть проект ZIP','import-project')}${button('История сохранений','backups')}</div><div class="divider"></div><h3>Быстрый старт</h3><p class="help">1. Создайте персонажей и ресурсы.<br>2. Добавьте сцены и события.<br>3. Настройте интерфейс.<br>4. Проверьте и экспортируйте в Ren’Py.</p></div></div>`}
function eventSummary(e){switch(e.type){case'say':return (P.characters.find(c=>c.id===e.character)?.name||'Рассказчик')+': '+(e.text||'');case'choice':return (e.options||[]).map(o=>o.text+' → '+o.target).join(' · ');case'condition':return e.expression+' → '+e.yes+' / '+e.no;case'set':return e.variable+' = '+e.value;default:return e.asset||e.target||e.character||e.text||e.game||e.id||e.plugin||e.value||''}}
function stageHTML(state={},interactive=false){let ui=P.interface, c=P.characters.find(c=>c.id===(state.character||P.characters[0]?.id)), bg=state.background||assets.find(a=>/court/.test(a.name))?.name;return `<div class="stage" id="stage" style="background:${esc(ui.background)}">${bg?`<img class="bg" src="${assetURL(bg)}">`:''}${c?.sprite&&!state.hide?`<img class="sprite" src="${assetURL(c.sprite)}" style="left:${({left:5,center:32,right:60})[state.position||'right']}%;height:${({small:52,medium:68,large:82})[c.height]}%">`:''}${ui.elements.map((el,i)=>`<div class="hud ${interactive&&i===selectedObject?'selected':''}" data-hud="${i}" style="left:${el.x*100}%;top:${el.y*100}%;width:${el.width/12.8}%;font-size:clamp(10px,1.3vw,20px);color:${esc(ui.text)}">${esc(el.label)}${el.type==='bar'?'<div class="hudbar"></div>':''}${el.type==='button'?' ↗':''}</div>`).join('')}<div class="dialogue" style="top:${ui.textboxY*100}%;height:${ui.textboxH*100}%;background:${esc(ui.panel)}ed;color:${esc(ui.text)};font-size:${ui.fontSize/1.8}px"><b style="color:${esc(c?.color||ui.accent)}">${esc(state.narrator?'':c?.name||'Рассказчик')}</b><span>${esc(state.text||'У каждой истории есть начало. Каким будет ваше?')}</span></div></div>`}
function storyView(){let s=P.scenes[sceneIndex]||P.scenes[0];if(!s)return heading('Сценарий','Создайте первую сцену',button('＋ Сцена','add-scene','primary'));eventIndex=Math.max(0,Math.min(eventIndex,s.events.length-1));let e=s.events[eventIndex];return heading('Сценарий','Сцены связываются выборами и переходами. События можно перетаскивать.',button(graph?'Лента событий':'Карта ветвлений','toggle-graph')+button('＋ Сцена','add-scene','primary')+button('Word','import-word'))+(graph?graphView():`<div class="split"><div><div class="scene-list">${P.scenes.map((x,i)=>`<div class="scene-item ${sceneIndex===i?'active':''}" data-scene="${i}"><b>${esc(x.name)}</b><small>${esc(x.id)} · ${x.events.length} событий ${x.id===P.start?'· старт':''}</small></div>`).join('')}</div><div class="card" style="margin-top:16px"><h3>Переменные</h3>${P.variables.map((v,i)=>`<div class="row" style="margin-top:10px"><span>${esc(v.id)} = ${esc(v.value)}</span><button data-var="${i}">✎</button><button data-delvar="${i}">×</button></div>`).join('')}<div style="margin-top:12px">${button('＋ Переменная','add-variable')}</div></div></div><div><div class="card" style="margin-bottom:15px"><div id="sceneform">${field('Название сцены','name',s.name)}${field('ID сцены (латиница)','id',s.id)}</div><div class="row">${button('Дублировать сцену','duplicate-scene')}${button('Удалить','delete-scene','danger')}</div></div><div class="timeline">${s.events.map((x,i)=>`<div class="event ${i===eventIndex?'active':''}" draggable="true" data-event="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><div class="info"><b>${names[x.type]||esc(x.type)}</b><small>${esc(eventSummary(x))}</small></div><button data-up="${i}" title="Выше">↑</button><button data-down="${i}" title="Ниже">↓</button></div>`).join('')||'<div class="empty">Добавьте первое событие</div>'}</div><div class="row" style="margin-top:15px"><select id="new-event" style="flex:1">${Object.entries(names).map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select>${button('＋ Событие','add-event','primary')}</div></div><div class="card inspector"><h3>${e?names[e.type]:'Свойства события'}</h3>${e?`<div id="eventform">${eventForm(e)}</div><div class="divider"></div><div class="row">${button('Копия','duplicate-event')}${button('Удалить','delete-event','danger')}</div>`:'<p class="help">Выберите или добавьте событие.</p>'}</div></div>`)}
function graphView(){return `<div class="graph">${P.scenes.map((s,i)=>{let links=s.events.flatMap(e=>e.type==='choice'?(e.options||[]).map(o=>[o.target,o.text]):e.type==='condition'?[[e.yes,'Да'],[e.no,'Нет']]:e.type==='jump'?[[e.target,'Переход']]:[]);return `<div class="card node"><span class="tag">${esc(s.id)}${s.id===P.start?' · СТАРТ':''}</span><h3 style="margin:10px 0">${esc(s.name)}</h3><p>${s.events.length} событий</p><div class="links">${links.map(([t,l])=>`${esc(l)} → ${esc(P.scenes.find(s=>s.id===t)?.name||t)}`).join('<br>')||'Завершение сцены'}</div><button style="margin-top:15px" data-scene="${i}">Открыть →</button></div>`}).join('')}</div>`}
function eventForm(e){let t=e.type, html='';if(t==='say')html=sel('Говорящий','character',e.character,charOptions())+area('Текст реплики','text',e.text);if(['background','music','sound','video'].includes(t)){let regex=t==='background'?/\.(png|jpe?g|webp)$/i:t==='video'?/\.(mp4|webm|ogv)$/i:/\.(ogg|mp3|wav|opus)$/i;html=sel('Ресурс','asset',e.asset,assetOptions(regex))+`<p class="help">Файлы загружаются во вкладке «Ресурсы».</p>`}if(['show','hide'].includes(t))html=sel('Персонаж','character',e.character,P.characters.map(c=>[c.id,c.name]));if(t==='show')html+=sel('Положение','position',e.position,[['left','Слева'],['center','По центру'],['right','Справа']]);if(['background','show','hide','effect'].includes(t))html+=sel('Эффект','effect',e.effect||'dissolve',effects);if(t==='jump')html=sel('Перейти в сцену','target',e.target,sceneOptions());if(t==='set')html=sel('Переменная','variable',e.variable,P.variables.map(v=>v.id))+field('Значение или выражение','value',e.value)+`<small>Например: trust + 1, True, "вечер"</small>`;if(t==='condition')html=field('Условие','expression',e.expression)+sel('Если истина','yes',e.yes,sceneOptions())+sel('Иначе','no',e.no,sceneOptions())+'<small>Например: trust &gt;= 3 and day == 2</small>';if(['day','pause'].includes(t))html=field(t==='day'?'Номер дня':'Длительность, секунд','value',e.value,'number','min="0" step="0.1"');if(t==='ending')html=area('Текст концовки','text',e.text)+check('Показать титры','credits',e.credits);if(t==='achievement')html=sel('Достижение','id',e.id,P.achievements.map(a=>[a.id,a.name]));if(t==='cutscene')html=sel('Катсцена','id',e.id,P.cutscenes.map(c=>[c.id,c.id]));if(t==='minigame')html=sel('Мини-игра','game',e.game,P.minigames.map(g=>[g.id,g.title]))+sel('Сохранить результат в','variable',e.variable,varOptions());if(t==='python')html=sel('Подключенный модуль','plugin',e.plugin,P.python.map(x=>[x.id,x.id]))+sel('Результат в переменную','variable',e.variable,varOptions())+'<p class="help">Python запускается в Ren’Py. Подключайте только доверенные файлы.</p>';if(t==='credits')html='<p class="help">Титры редактируются во вкладке «Видео и титры».</p>';if(t==='stop_music')html='<p class="help">Музыка затихнет за одну секунду.</p>';if(t==='choice')html=(e.options||[]).map((o,i)=>`<div class="card" style="padding:12px;margin-top:12px" data-option="${i}">${field('Текст варианта','text',o.text)}${sel('Сцена','target',o.target,sceneOptions())}${field('Условие доступности (необязательно)','condition',o.condition||'')}<button data-deloption="${i}">Удалить вариант</button></div>`).join('')+button('＋ Вариант','add-option');return html}
function charactersView(){return heading('Ваши персонажи','Настройте имя, цвет, спрайт и рост. Встроенный редактор поможет собрать простого героя.',button('＋ Персонаж','add-character','primary')+button('Собрать спрайт','goto-art'))+`<div class="grid">${P.characters.map((c,i)=>`<div class="card" data-character="${i}"><div style="height:180px;text-align:center;background:#111521;border-radius:9px">${c.sprite?`<img style="height:100%;max-width:100%;object-fit:contain" src="${assetURL(c.sprite)}">`:'<span class="stat">♙</span>'}</div>${field('ID (латиница)','id',c.id)}${field('Имя','name',c.name)}${field('Цвет имени','color',c.color,'color')}${sel('Спрайт','sprite',c.sprite,assetOptions(/\.(png|jpe?g|webp)$/i))}${sel('Рост','height',c.height,[['small','Маленький'],['medium','Средний'],['large','Большой']])}<button class="danger" data-delcharacter="${i}">Удалить персонажа</button></div>`).join('')}</div>`}
function assetsView(){return heading('Библиотека ресурсов','Изображения, музыка, видео и Python. Файлы копируются внутрь проекта.',button('＋ Загрузить файлы','upload-assets','primary'))+`<p class="help">PNG, JPG, WebP · OGG, MP3, WAV · WebM, OGV, MP4 · PY, RPY. До 256 МБ на файл. Для видео рекомендуется WebM/OGV. Для прозрачных спрайтов — PNG.</p><div class="grid">${assets.map(a=>`<div class="card asset">${/\.(png|jpe?g|webp)$/i.test(a.name)?`<img src="${assetURL(a.name)}">`:/\.(ogg|mp3|wav|opus)$/i.test(a.name)?`<audio controls src="${assetURL(a.name)}"></audio>`:/\.(webm|mp4|ogv)$/i.test(a.name)?`<video controls src="${assetURL(a.name)}"></video>`:'<div class="empty">Python модуль</div>'}<h3 class="filename">${esc(a.name)}</h3><small>${(a.size/1024).toFixed(1)} КБ</small><div style="margin-top:12px"><a class="btn" download="${esc(a.name)}" href="${assetURL(a.name)}">Скачать</a></div></div>`).join('')||'<div class="empty">Загрузите первый ресурс</div>'}</div>`}
let art={mode:'background',preset:'court',sky:'#8cb5d5',ground:'#456676',skin:'#efd0b8',hair:'#3c2841',shirt:'#b49aff',pants:'#273449',expression:'smile',hairStyle:'short',name:'my_background.png',objects:[]};
function artView(){return heading('Мастерская изображений','Фоны из геометрических объектов и персонажи из настраиваемых деталей.',button('Сохранить PNG в ресурсы','save-art','primary'))+`<div class="editorcols"><div><div class="canvas-wrap"><canvas id="artcanvas" width="1280" height="720"></canvas></div><p class="help">В режиме фона добавляйте объекты и перетаскивайте их мышью. Сохраненный PNG можно выбрать в событиях и у персонажей. Спрайт сохраняется с прозрачным фоном.</p></div><div class="card" id="artform">${sel('Сохраненные исходники','savedBoard','',[['','Новый рисунок'],...(P.artboards||[]).map((b,i)=>[String(i),b.file])])}${button('Открыть исходник','load-art')}<div class="divider"></div>${sel('Что создаем','mode',art.mode,[['background','Фон'],['character','Спрайт персонажа']])}${art.mode==='background'?sel('Основа','preset',art.preset,[['court','Волейбольная площадка'],['room','Комната'],['city','Город'],['forest','Лес'],['blank','Чистый фон']])+field('Небо / стена','sky',art.sky,'color')+field('Земля / пол','ground',art.ground,'color')+`<div class="row">${button('＋ Прямоугольник','add-rect')}${button('＋ Круг','add-circle')}${button('＋ Текст','add-arttext')}${button('Удалить объект','del-artobject')}</div>`:field('Тон кожи','skin',art.skin,'color')+field('Волосы','hair',art.hair,'color')+sel('Прическа','hairStyle',art.hairStyle,[['short','Короткая'],['long','Длинная'],['spiky','Взъерошенная']])+field('Верх','shirt',art.shirt,'color')+field('Низ','pants',art.pants,'color')+sel('Выражение','expression',art.expression,[['smile','Улыбка'],['sad','Грусть'],['surprise','Удивление']])}${field('Имя PNG (латиница)','name',art.name)}<div id="artobjectform"></div></div></div>`}
let artSelection=-1;
function drawArt(){let canvas=$('#artcanvas');if(!canvas)return;canvas.width=art.mode==='character'?600:1280;canvas.height=art.mode==='character'?900:720;let c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);const rect=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(x,y,w,h)},circle=(x,y,r,col)=>{c.fillStyle=col;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill()},line=(x,y,x2,y2,col,width=5)=>{c.strokeStyle=col;c.lineWidth=width;c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke()};
 if(art.mode==='character'){if(art.hairStyle==='long'){c.fillStyle=art.hair;c.beginPath();c.ellipse(300,245,140,210,0,0,Math.PI*2);c.fill()}rect(220,530,70,300,art.pants);rect(310,530,70,300,art.pants);rect(203,817,90,42,'#171e2a');rect(307,817,95,42,'#171e2a');c.fillStyle=art.shirt;c.beginPath();c.moveTo(211,298);c.lineTo(385,298);c.lineTo(420,590);c.lineTo(181,590);c.closePath();c.fill();line(215,325,150,550,art.shirt,65);line(385,325,450,550,art.shirt,65);circle(146,558,30,art.skin);circle(454,558,30,art.skin);rect(272,250,55,80,art.skin);c.fillStyle=art.skin;c.beginPath();c.ellipse(300,192,99,123,0,0,Math.PI*2);c.fill();c.fillStyle=art.hair;c.beginPath();c.ellipse(300,110,112,72,0,Math.PI,Math.PI*2);c.lineTo(412,167);c.lineTo(354,126);c.lineTo(330,176);c.lineTo(290,132);c.lineTo(229,180);c.lineTo(190,151);c.fill();if(art.hairStyle==='spiky'){c.beginPath();c.moveTo(190,110);c.lineTo(185,30);c.lineTo(250,65);c.lineTo(295,12);c.lineTo(338,60);c.lineTo(405,29);c.lineTo(410,120);c.fill()}circle(262,195,9,'#282639');circle(338,195,9,'#282639');circle(260,192,2,'white');circle(336,192,2,'white');c.strokeStyle='#704c54';c.lineWidth=5;c.beginPath();if(art.expression==='smile')c.arc(300,230,27,.1,Math.PI-.1);else if(art.expression==='sad')c.arc(300,258,25,Math.PI+.2,Math.PI*2-.2);else c.ellipse(300,247,12,20,0,0,Math.PI*2);c.stroke();}
 else{let grad=c.createLinearGradient(0,0,0,520);grad.addColorStop(0,art.sky);grad.addColorStop(1,'#dae0e6');c.fillStyle=grad;c.fillRect(0,0,w,h);rect(0,440,w,280,art.ground);if(art.preset==='court'){rect(100,460,1080,220,'#b58b68');c.strokeStyle='white';c.lineWidth=5;c.strokeRect(150,480,980,170);line(640,460,640,680,'#ffffff');line(100,350,1180,350,'#d9e4e9');line(100,350,100,620,'#334454',12);line(1180,350,1180,620,'#334454',12);for(let x=100;x<=1180;x+=30)line(x,350,x,435,'#d9e4e9',2);for(let y=350;y<=435;y+=17)line(100,y,1180,y,'#d9e4e9',2);circle(1080,100,45,'#fff4cf')}if(art.preset==='room'){rect(470,120,350,260,'#42536f');rect(485,135,320,230,'#a2cadd');line(645,135,645,365,'#eee',8);rect(80,420,300,180,'#69546e');rect(850,460,280,25,'#594a51');rect(875,485,20,155,'#594a51');rect(1090,485,20,155,'#594a51')}if(art.preset==='city'){for(let i=0;i<10;i++){let bh=120+(i*67)%220;rect(i*140,440-bh,120,bh,['#525e78','#747995','#59647e'][i%3]);for(let x=0;x<3;x++)for(let y=0;y<4;y++)rect(i*140+15+x*33,455-bh+y*42,16,24,'#dfd9af')}rect(0,540,w,180,'#414653');for(let x=30;x<w;x+=160)rect(x,625,90,8,'#e7e4c4')}if(art.preset==='forest'){for(let i=0;i<12;i++){let x=i*117;rect(x+25,300,22,220,'#6b4c4e');circle(x+36,250,95,['#3d7268','#4d8a75','#345e61'][i%3])}}art.objects.forEach((o,i)=>{if(o.kind==='circle')circle(o.x,o.y,o.w/2,o.color);else if(o.kind==='text'){c.fillStyle=o.color;c.font=`${o.h||50}px sans-serif`;c.fillText(o.text||'Текст',o.x,o.y)}else rect(o.x,o.y,o.w,o.h,o.color);if(i===artSelection){c.strokeStyle='#ffffff';c.lineWidth=3;c.setLineDash([8,5]);c.strokeRect(o.x-(o.kind==='circle'?o.w/2:0),o.y-(o.kind==='circle'?o.w/2:o.kind==='text'?o.h:0),o.w,o.kind==='circle'?o.w:o.h);c.setLineDash([])}})}
 canvas.onpointerdown=e=>{if(art.mode!=='background')return;let r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*w/r.width,y=(e.clientY-r.top)*h/r.height;artSelection=art.objects.findLastIndex(o=>o.kind==='circle'?Math.hypot(x-o.x,y-o.y)<o.w/2:x>=o.x&&x<=o.x+o.w&&y>=o.y-(o.kind==='text'?o.h:0)&&y<=o.y+(o.kind==='text'?0:o.h));if(artSelection<0)return;let o=art.objects[artSelection],dx=x-o.x,dy=y-o.y;canvas.setPointerCapture(e.pointerId);canvas.onpointermove=ev=>{o.x=Math.round((ev.clientX-r.left)*w/r.width-dx);o.y=Math.round((ev.clientY-r.top)*h/r.height-dy);drawArt()};canvas.onpointerup=()=>{canvas.onpointermove=null;artObjectForm()};drawArt();artObjectForm()};}
function artObjectForm(){let o=art.objects[artSelection];$('#artobjectform').innerHTML=o?'<div class="divider"></div>'+field('Цвет объекта','color',o.color,'color')+field('Ширина','w',o.w,'number')+field(o.kind==='text'?'Размер текста':'Высота','h',o.h,'number')+(o.kind==='text'?field('Текст','text',o.text):''):'';$$('#artobjectform input').forEach(el=>el.oninput=()=>{o[el.name]=el.type==='number'?Number(el.value):el.value;drawArt()})}
function cinemaView(){return heading('Видео, катсцены и титры','Используйте готовый видеоролик или соберите последовательность титульных карточек.')+`<div class="grid two"><div class="card"><h2>Заставка перед главным меню</h2><div id="introform">${sel('Готовое видео (имеет приоритет)','video',P.intro.video,assetOptions(/\.(webm|ogv|mp4)$/i))}</div><p class="help">Если видео не выбрано, игра покажет карточки с плавными переходами.</p>${cardsForm(P.intro.cards,'intro')}${button('＋ Карточка','add-intro-card')}${button('Просмотреть','preview-intro')}</div><div class="card"><h2>Титры</h2><div id="creditsform">${field('Заголовок','title',P.credits.title)}${area('Текст — автор на каждой строке','lines',P.credits.lines)}${field('Автозакрытие, секунд','seconds',P.credits.seconds,'number','min="1"')}</div><p class="help">Титры можно прокручивать мышью и закрыть кнопкой. Добавляйте событие «Титры» или включите их в концовке.</p></div></div><div class="heading" style="margin-top:25px"><h2>Сюжетные катсцены</h2>${button('＋ Катсцена','add-cutscene','primary')}</div>${P.cutscenes.map((c,i)=>`<div class="card listcard"><div data-cutscene="${i}">${field('ID катсцены','id',c.id)}</div>${cardsForm(c.cards,'cut-'+i)}<div class="row"><button data-addcard="${i}">＋ Карточка</button><button data-previewcut="${i}">Просмотреть</button><button class="danger" data-delcut="${i}">Удалить катсцену</button></div></div>`).join('')}<p class="help">Конструктор создает катсцену, исполняемую движком: текст, изображение, цвет и длительность каждой карточки. Для анимации персонажей используйте события «Показать героя», «Эффект», «Пауза» в сценах. Это не нейросетевая генерация видео.</p>`}
function cardsForm(cards,owner){return cards.map((c,i)=>`<div class="card listcard" data-card="${owner}:${i}" style="padding:12px;margin-top:14px"><h3>Карточка ${i+1}</h3>${area('Текст','text',c.text)}${field('Цвет фона','background',c.background,'color')}${sel('Изображение вместо цвета','asset',c.asset,assetOptions(/\.(png|jpe?g|webp)$/i))}${field('Длительность, секунд','seconds',c.seconds,'number','min="0.1" step="0.1"')}<button data-cardmove="${owner}:${i}:-1">↑</button> <button data-cardmove="${owner}:${i}:1">↓</button> <button data-delcard="${owner}:${i}">Удалить</button></div>`).join('')}
function interfaceView(){let ui=P.interface,el=ui.elements[selectedObject];return heading('Интерфейс вашей игры','Собственная тема меню и диалогов. Элементы HUD можно двигать прямо на сцене.',button('＋ Элемент','add-ui','primary'))+`<div class="editorcols"><div>${stageHTML({},true)}<div class="grid">${['violet','ocean','paper'].map((p,i)=>`<button data-preset="${p}" class="card"><b>${['Ночная сирень','Океан','Светлая бумага'][i]}</b><div style="height:35px;border-radius:5px;margin-top:10px;background:${['linear-gradient(90deg,#111126,#ad93ff)','linear-gradient(90deg,#081c2a,#72decf)','linear-gradient(90deg,#e9e2d2,#955e45)'][i]}"></div></button>`).join('')}</div><div class="card" style="margin-top:18px"><h3>Элементы интерфейса</h3><div class="row" style="margin-top:12px">${ui.elements.map((e,i)=>`<button data-ui="${i}" class="${i===selectedObject?'primary':''}">${esc(e.label||e.type)}</button>`).join('')}</div><p class="help">Кнопки выполняют переход в сцену. Шкалы отображают переменные. Меню, сохранения, настройки и выборы генерируются в выбранной теме.</p></div></div><div><div class="card" id="uiform"><h3>Тема и диалоговое окно</h3>${field('Акцент','accent',ui.accent,'color')}${field('Фон меню','background',ui.background,'color')}${field('Панели','panel',ui.panel,'color')}${field('Цвет текста','text',ui.text,'color')}${field('Позиция окна по Y (0–1)','textboxY',ui.textboxY,'number','min="0" max="1" step="0.01"')}${field('Высота окна (0–1)','textboxH',ui.textboxH,'number','min="0.1" max="1" step="0.01"')}${field('Размер текста','fontSize',ui.fontSize,'number','min="12" max="100"')}${field('Размер имени','nameSize',ui.nameSize,'number','min="12" max="100"')}</div>${el?`<div class="card" style="margin-top:18px" id="uielementform"><h3>Выбранный элемент</h3>${sel('Тип','type',el.type,[['text','Надпись'],['bar','Шкала'],['button','Кнопка перехода']])}${field('Подпись','label',el.label)}${field('X (0–1)','x',el.x,'number','min="0" max="1" step="0.01"')}${field('Y (0–1)','y',el.y,'number','min="0" max="1" step="0.01"')}${field('Ширина в пикселях 1280×720','width',el.width,'number','min="20" max="1280"')}${el.type==='bar'?sel('Переменная','variable',el.variable,P.variables.map(v=>v.id))+field('Максимум','max',el.max||10,'number','min="1"'):''}${el.type==='button'?sel('Сцена перехода','target',el.target,sceneOptions()):''}${button('Удалить элемент','del-ui','danger')}</div>`:''}</div></div>`}
function minigamesView(){return heading('Мини-игры','Четыре готовые механики с настройками. Результат можно использовать в условиях сюжета.',button('＋ Мини-игра','add-minigame','primary'))+`<div class="grid two">${P.minigames.map((g,i)=>`<div class="card" data-minigame="${i}">${field('ID','id',g.id)}${field('Название','title',g.title)}${sel('Механика','kind',g.kind,[['quiz','Викторина'],['clicker','Кликер'],['timing','Попадание в зону'],['volleyball','Ловля волейбольного мяча']])}${field('Цель в очках','target',g.target,'number','min="1"')}${field('Лимит времени, секунд','seconds',g.seconds,'number','min="1"')}${g.kind==='quiz'?area('Вопрос','question',g.question)+(g.answers||[]).map((a,j)=>`<div data-answer="${i}:${j}">${field('Ответ '+(j+1),'text',a.text)}${check('Правильный','correct',a.correct)}<button data-delanswer="${i}:${j}">Удалить ответ</button></div>`).join('')+`<button data-addanswer="${i}">＋ Ответ</button>`:'<p class="help">'+({clicker:'Наберите очки кликами до конца времени.',timing:'Нажмите пробел в зеленой зоне.',volleyball:'Передвигайте платформу стрелками или кнопками и ловите мяч. Это простая сюжетная мини-игра.'}[g.kind]||'Размещайте объекты в конструкторе поля ниже.')+'</p>'}<div class="row" style="margin-top:15px"><button data-testmini="${i}">▷ Проверить</button><button class="danger" data-delmini="${i}">Удалить</button></div></div>`).join('')}</div>`}
function steamView(){return heading('Steam и Python','Достижения, настройки Steamworks и подключение собственных игровых механик.')+`<div class="grid two"><div class="card"><h2>Настройки Steam</h2><div id="steamform">${check('Создавать steam_appid.txt для тестирования','enabled',P.steam.enabled)}${field('Steam App ID','appid',P.steam.appid)}</div><p class="help">В Ren’Py Launcher установите Steam support. В Steamworks создайте достижения с теми же API-именами и опубликуйте настройки. Сам Steam SDK и аккаунт партнера в комплект не входят. Без Steam достижения работают локально средствами Ren’Py.</p><h3>Достижения</h3>${P.achievements.map((a,i)=>`<div class="card listcard" data-achievement="${i}" style="margin-top:14px">${field('ID в игре','id',a.id)}${field('API-имя в Steamworks','steam',a.steam)}${field('Название','name',a.name)}${field('Описание','description',a.description)}<button data-delachievement="${i}">Удалить</button></div>`).join('')}${button('＋ Достижение','add-achievement')}</div><div class="card"><h2>Свои мини-игры на Python</h2><p class="help">Загрузите .py или .rpy в «Ресурсы», затем подключите здесь. Вставьте событие «Python модуль» в нужный момент сюжета. Сервер редактора код не исполняет.</p>${P.python.map((x,i)=>`<div class="card listcard" data-python="${i}">${field('ID модуля','id',x.id)}${sel('Режим','mode',x.mode,[['function','Функция из .py'],['label','Ren’Py label из .rpy']])}${sel('Файл','asset',x.asset,assetOptions(/\.(py|rpy)$/i))}${field('Имя функции / label','function',x.function)}<button data-delpython="${i}">Удалить подключение</button></div>`).join('')}${button('＋ Подключение','add-python')}<details style="margin-top:20px"><summary>Пример интеграции</summary><pre># custom.py — возвращает число\ndef run():\n    import renpy\n    renpy.say(None, "Ваша мини-игра")\n    return 5</pre><pre># custom.rpy — доступ ко всем экранам Ren’Py\nlabel volleyball_custom:\n    call screen my_volleyball\n    return _return</pre><p class="help">Для интерактивных игр предпочтителен .rpy: screen language, таймеры и call screen сохраняют игровой цикл Ren’Py. Python-модули должны быть совместимы с Python выбранного SDK; зависимости устанавливаются отдельно.</p></details></div></div>`}
function exportView(){return heading('Проверка и выпуск','Получите редактируемый проект Ren’Py или запустите его через установленный SDK.')+`<div class="grid two"><div class="card"><h2>Готовность проекта</h2><p class="help">Проверяем ID, ресурсы, условия, переходы и настройки. Проверка Ren’Py также проверит сгенерированные скрипты и ваши плагины.</p><div class="row">${button('Проверить проект','validate','primary')}${button('Проверить через SDK (lint)','lint')}</div><div id="report" style="margin-top:18px"></div><div class="divider"></div><div class="row">${button('Скачать проект Ren’Py ZIP','export-renpy','primary')}<a class="btn" data-download="word" href="/download/${id}/word">Сценарий Word</a></div><p class="help">ZIP содержит game/*.rpy, ресурсы и JSON проекта. Распакуйте в папку проектов Launcher. Для EXE и других платформ используйте «Построить дистрибутивы» в Ren’Py.</p></div><div class="card"><h2>Ren’Py SDK на компьютере</h2><div id="sdkform">${field('Путь к распакованной папке SDK','path',sdk)}</div><div class="row">${button('Подключить SDK','set-sdk')}${button('▷ Запустить игру','run','primary')}</div><p class="help">Например: C:\\RenPy\\renpy-8.5.3-sdk. Для старых версий укажите SDK 7.4+ и выберите профиль 7 в обзоре. Совместимость сторонних Python-модулей проверяется отдельно.</p><pre id="sdklog">${sdk?'SDK подключен: '+esc(sdk):'SDK пока не выбран'}</pre></div></div>`}
function helpView(){return heading('Руководство','Рабочий процесс от первого героя до сборки игры.')+`<div class="grid two"><div class="card"><h2>Начало работы</h2><p class="help">Демонстрационная история уже готова. Откройте «Сценарий», выберите сцену и событие. Поменяйте реплику в правой панели. Для перехода между сценами используйте «Выбор», «Переход» или «Условие». В конце каждой ветки добавляйте концовку или переход: пустой конец сцены завершает игру.</p><h3>Данные и отмена</h3><p class="help">Изменения сохраняются автоматически. Ctrl+S — сохранить; Ctrl+Z/Ctrl+Shift+Z вне полей — отмена/повтор. Сохраняются последние 30 резервных версий JSON. Ресурсы копируются в проект. Для переноса используйте ZIP в обзоре.</p><h3>Предпросмотр</h3><p class="help">Браузерный проигрыватель показывает диалоги, ветвления, фоны, героев, музыку, видео и карточки. Условия вычисляются ограниченным интерпретатором. Python-плагины выполняются только в Ren’Py. Для проверки сохранений, точной верстки, достижений и поведения движка запускайте игру через SDK.</p><h3>Что поддерживается</h3><p class="help">Профили Ren’Py 7.4+ и 8.x используют общий синтаксис. Сборки 6.x, Python 2-плагины на Ren’Py 8 и неизвестные расширения автоматически не конвертируются. На приложенном SDK 8.5.3 выполнены проверки; перед выпуском прогоните игру на нужных ОС и версиях.</p><h3>Безопасность плагинов</h3><p class="help">Код .py и .rpy получает права запущенной игры. Подключайте свои или проверенные файлы. Не вводите API-ключи и пароли в параметры проекта.</p></div><div class="card"><h2>Сценарий из Word</h2><p class="help">Поддерживается .docx, не старый бинарный .doc. Скачайте шаблон с русскими командами: «Команда / Объект ID / Текст или файл / Параметры». Для реплик достаточно указать персонажа и текст; для ресурсов — имя файла. Дополнительные настройки задаются через точку с запятой, например позиция=справа; эффект=плавно. Экспорт полного сценария также поддерживает расширенный двухколоночный формат JSON. Свободный текст без разметки команд не угадывается автоматически. Импорт заменяет сцены и обновляет остальные сущности по ID; перед импортом создается резервная копия.</p><a class="btn" href="/download/${id}/template">Скачать шаблон</a><div class="divider"></div><div class="commandlist">${[['project','Название, start, target'],['character','id, name, color, sprite, height'],['variable','id, value'],['scene','id, name — начало сцены'],['say','character, text'],['show','character, position, effect'],['background','asset, effect'],['music / sound','asset'],['choice','options: [{text,target,condition}]'],['condition','expression, yes, no'],['set','variable, value — выражение строкой'],['jump','target'],['day / pause','value'],['video','asset'],['cutscene','id, cards; в сцене — id'],['minigame','Объявление с kind; вызов с game, variable'],['achievement','Объявление с name; вызов с id'],['python','Объявление с asset; вызов с plugin'],['ending','text, credits']].map(([a,b])=>`<code>${a}</code><small>${b}</small>`).join('')}</div><p class="help">Объявления minigame / achievement / python / cutscene ставьте до первой scene. Внутри scene эти команды — события. Полный формат проще получить кнопкой «Сценарий Word» на вкладке «Экспорт».</p></div></div>`}
function formBind(selector,obj,opts={}){$$(selector+' input,'+selector+' select,'+selector+' textarea').forEach(el=>{el.onchange=()=>{snapshot();let old=obj[el.name],value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;obj[el.name]=value;if(obj.type==='show'&&el.name==='character')obj.variant='';if(opts.reference&&el.name==='id')renameReferences(opts.reference,old,value);changed();if(opts.rerender!==false)render()}})}
function renameReferences(collection,old,value){for(let s of P.scenes){for(let e of s.events){if(collection==='scenes'){for(let k of ['target','yes','no'])if(e[k]===old)e[k]=value;for(let o of e.options||[])if(o.target===old)o.target=value}if(collection==='characters'&&e.character===old)e.character=value;if(collection==='minigames'&&e.game===old)e.game=value;if(collection==='cutscenes'&&e.type==='cutscene'&&e.id===old)e.id=value;if(collection==='achievements'&&e.type==='achievement'&&e.id===old)e.id=value;if(collection==='python'&&e.plugin===old)e.plugin=value;if(collection==='variables'){if(e.variable===old)e.variable=value;for(let k of ['expression','value'])if(typeof e[k]==='string')e[k]=e[k].replace(new RegExp('\\b'+old+'\\b','g'),value);for(let o of e.options||[])if(o.condition)o.condition=o.condition.replace(new RegExp('\\b'+old+'\\b','g'),value)}}}if(collection==='scenes'){if(P.start===old)P.start=value;for(let el of P.interface.elements)if(el.target===old)el.target=value}if(collection==='variables')for(let el of P.interface.elements)if(el.variable===old)el.variable=value}
