function unique(prefix,collection){let n=1;while(P[collection].some(o=>o.id===prefix+n))n++;return prefix+n}
function newEvent(type){let common={type};return Object.assign(common,({say:{character:P.characters[0]?.id||'',text:'Новая реплика'},background:{asset:'',effect:'dissolve'},show:{character:P.characters[0]?.id||'',position:'center',effect:'dissolve'},hide:{character:P.characters[0]?.id||'',effect:'dissolve'},music:{asset:''},sound:{asset:''},video:{asset:''},choice:{options:[{text:'Продолжить',target:P.scenes[0]?.id}]},jump:{target:P.scenes[0]?.id},condition:{expression:'True',yes:P.scenes[0]?.id,no:P.scenes[0]?.id},set:{variable:P.variables[0]?.id,value:'0'},day:{value:1},ending:{text:'Конец',credits:true},cutscene:{id:P.cutscenes[0]?.id},minigame:{game:P.minigames[0]?.id,variable:''},python:{plugin:P.python[0]?.id,variable:''},achievement:{id:P.achievements[0]?.id},pause:{value:1},effect:{effect:'hpunch'}}[type])||{})}
async function chooseFiles(accept,multiple,fn){let el=$('#file');el.value='';el.accept=accept;el.multiple=multiple;el.onchange=async()=>{try{await fn([...el.files])}catch(e){toast(e.message)}};el.click()}
function b64(file){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Не удалось прочитать файл'));reader.readAsDataURL(file)})}
