function showReport(r){$('#report').innerHTML=(r.errors.length?'<h3 class="error">Ошибки</h3>'+r.errors.map(x=>'<p class="error">• '+esc(x)+'</p>').join(''):'<p class="ok">✓ Структура проекта проверена. Ошибок не найдено.</p>')+(r.warnings.length?'<h3 style="margin-top:15px" class="warn">Замечания</h3>'+r.warnings.map(x=>'<p class="warn">• '+esc(x)+'</p>').join(''):'')}
function editVariable(i){let v=i<0?{id:'value',value:0}:P.variables[i];modal('<div class="heading"><h2>Переменная</h2><button data-close>Закрыть</button></div><div id="varform">'+field('ID (латиница)','id',v.id)+sel('Тип','kind',typeof v.value,[['number','Число'],['boolean','Логическое'],['string','Текст']])+field('Начальное значение','value',v.value)+'</div><button id="savevar" class="primary">Сохранить</button>');$('#savevar').onclick=()=>{let name=$('#varform [name=id]').value,kind=$('#varform [name=kind]').value,value=$('#varform [name=value]').value;if(!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name))return toast('ID — латиница, цифры и подчеркивание');if(P.variables.some((x,j)=>x.id===name&&i!==j))return toast('Такой ID уже есть');if(kind==='number'){value=Number(value);if(!Number.isFinite(value))return toast('Нужно число')}if(kind==='boolean')value=['true','1','да'].includes(value.toLowerCase());snapshot();if(i<0)P.variables.push({id:name,value});else{let old=v.id;v.id=name;v.value=value;renameReferences('variables',old,name)}changed();closeModal();render()}}
function bindStageDrag(){$$('[data-hud]').forEach(el=>{el.onpointerdown=e=>{snapshot();selectedObject=+el.dataset.hud;let obj=P.interface.elements[selectedObject],stage=$('#stage'),r=stage.getBoundingClientRect(),dx=e.clientX-r.left-obj.x*r.width,dy=e.clientY-r.top-obj.y*r.height;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{obj.x=+Math.max(0,Math.min(.95,(ev.clientX-r.left-dx)/r.width)).toFixed(3);obj.y=+Math.max(0,Math.min(.95,(ev.clientY-r.top-dy)/r.height)).toFixed(3);el.style.left=obj.x*1280+'px';el.style.top=obj.y*720+'px'};el.onpointerup=()=>{el.onpointermove=null;changed();render()}}})}
function previewCards(cards,onDone){let i=0;function show(){if(i>=cards.length){if(onDone)onDone();else closeModal();return}let c=cards[i++];modal(`<div class="heading"><h2>Катсцена · ${i}/${cards.length}</h2><button data-close>Закрыть</button></div><div class="stage" style="background:${esc(c.background||'#111126')}">${c.asset?`<img class="bg" src="${assetURL(c.asset)}">`:''}<div style="position:absolute;inset:0;display:grid;place-items:center;padding:50px;color:white;font-size:30px;text-align:center;text-shadow:0 2px 4px black">${esc(c.text)}</div></div>`);clearInterval(previewTimer);previewTimer=setTimeout(show,Math.max(.1,c.seconds||2)*1000)}show()}
// Small expression interpreter. No eval, Function, attribute access, or Python execution.
function evalExpr(source,vars){let tokens=[],pattern=/\s*(>=|<=|==|!=|[()+*/%<>-]|\+|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\d+(?:\.\d+)?|[A-Za-z_][A-Za-z0-9_]*)/gy,pos=0;while(pos<source.length){if(!source.slice(pos).trim())break;pattern.lastIndex=pos;let m=pattern.exec(source);if(!m)throw Error('Неизвестное выражение: '+source);tokens.push(m[1]);pos=pattern.lastIndex}let i=0,peek=()=>tokens[i],next=()=>tokens[i++];function atom(){let t=next();if(t==='('){let v=or();if(next()!==')')throw Error('Не закрыта скобка');return v}if(t==='-'||t==='+'){let v=atom();return t==='-'?-v:+v}if(t==='True')return true;if(t==='False')return false;if(t==='None')return null;if(/^\d/.test(t||''))return Number(t);if(t?.startsWith('"'))return JSON.parse(t);if(t?.startsWith("'"))return t.slice(1,-1).replace(/\\'/g,"'");if(Object.hasOwn(vars,t))return vars[t];throw Error('Неизвестная переменная: '+t)}function mul(){let a=atom();while(['*','/','%'].includes(peek())){let op=next(),b=atom();a=op==='*'?a*b:op==='/'?a/b:a%b}return a}function add(){let a=mul();while(['+','-'].includes(peek())){let op=next(),b=mul();a=op==='+'?a+b:a-b}return a}function cmp(){let a=add(),result=true,had=false;while(['>','<','>=','<=','==','!='].includes(peek())){had=true;let op=next(),b=add();result=result&&({'>':()=>a>b,'<':()=>a<b,'>=':()=>a>=b,'<=':()=>a<=b,'==':()=>a===b,'!=':()=>a!==b}[op])();a=b}return had?result:a}function not(){if(peek()==='not'){next();return !not()}return cmp()}function and(){let a=not();while(peek()==='and'){next();let b=not();a=a&&b}return a}function or(){let a=and();while(peek()==='or'){next();let b=and();a=a||b}return a}let value=or();if(i!==tokens.length)throw Error('Лишние символы в выражении');return value}
function startPreview(){let vars=Object.fromEntries(P.variables.map(v=>[v.id,v.value])),s=P.scenes.find(s=>s.id===P.start),at=0,state={narrator:true,text:'',hide:true,people:{},objects:{}},ended=false,callStack=[],inlineStack=[];function jump(id){inlineStack=[];s=P.scenes.find(s=>s.id===id);at=0;if(!s)throw Error('Сцена не найдена: '+id)}function ui(options='',nextLabel='Далее →'){modal(`<div class="heading"><div><h2>${esc(P.title)}</h2><small>Предпросмотр · ${esc(s?.name||'')} · Python и достижения проверяются в Ren’Py</small></div><button data-close>Закрыть</button></div>${stageHTML(state)}<div id="preview-actions">${options||`<button class="primary" id="preview-next">${nextLabel}</button>`}</div><details style="margin-top:12px"><summary>Переменные</summary><pre>${esc(JSON.stringify(vars,null,2))}</pre></details>`);$('#preview-next')?.addEventListener('click',step)}
 function step(){clearInterval(previewTimer);try{let safety=0;while(!ended){if(++safety>500)throw Error('Слишком много переходов без реплик. Проверьте цикл.');let e=s?.events[at++];if(!e){if(inlineStack.length){let frame=inlineStack.pop();s=frame.scene;at=frame.at;if(frame.inline)inlineStack=frame.inline;continue}if(callStack.length){let frame=callStack.pop();s=frame.scene;at=frame.at;if(frame.inline)inlineStack=frame.inline;continue}ended=true;ui('<p>История завершена.</p>');return}switch(e.type){case'say':state.text=e.text;state.character=e.character;state.narrator=!e.character;ui();return;case'background':state.background=e.asset;state.hide=true;state.people={};state.objects={};break;case'show':state.character=e.character;state.position=e.position;state.spriteAsset=P.characters.find(c=>c.id===e.character)?.variants?.find(v=>v.id===e.variant)?.asset||'';state.hide=false;state.people[e.character]={...e,sprite:state.spriteAsset||P.characters.find(c=>c.id===e.character)?.sprite};break;case'hide':state.hide=true;delete state.people[e.character];break;case'image':state.objects[e.id]={...e};break;case'hide_image':delete state.objects[e.id];break;case'call':callStack.push({scene:s,at,inline:inlineStack.splice(0)});jump(e.target);break;case'return':inlineStack=[];if(callStack.length){let frame=callStack.pop();s=frame.scene;at=frame.at;inlineStack=frame.inline||[];break}ended=true;ui('<p>История завершена.</p>');return;case'raw':ui('<p class="warn">Этот блок выполняется только в Ren’Py.</p><pre>'+esc(e.code)+'</pre><button id="skipraw">Продолжить без выполнения блока</button>');$('#skipraw').onclick=step;return;case'jump':jump(e.target);break;case'condition':jump(evalExpr(e.expression,vars)?e.yes:e.no);break;case'branch':{let arm=e.branches.find(b=>!b.condition||evalExpr(b.condition,vars));if(arm){inlineStack.push({scene:s,at});s={...s,events:arm.events};at=0}break}case'menu_block':{let options=e.options.filter(o=>!o.condition||evalExpr(o.condition,vars));if(e.prompt){state.text=e.prompt;state.character='';state.narrator=true}ui(options.length?'<div class="preview-options">'+options.map((o,i)=>`<button data-inlinechoice="${i}">${esc(o.text)}</button>`).join('')+'</div>':'<p>Нет доступных вариантов.</p><button id="inline-empty-next">Продолжить</button>');$('#inline-empty-next')?.addEventListener('click',step);$$('[data-inlinechoice]').forEach(b=>b.onclick=()=>{inlineStack.push({scene:s,at});s={...s,events:options[+b.dataset.inlinechoice].events};at=0;step()});return}case'set':vars[e.variable]=evalExpr(String(e.value),vars);break;case'day':vars.day=e.value;state.text='День '+e.value;state.narrator=true;ui();return;case'choice':{let options=e.options.filter(o=>!o.condition||evalExpr(o.condition,vars));ui(options.length?'<div class="preview-options">'+options.map((o,i)=>`<button data-pvchoice="${i}">${esc(o.text)}</button>`).join('')+'</div>':'<p class="warn">Нет доступных вариантов. Проверьте условия.</p>');$$('[data-pvchoice]').forEach(b=>b.onclick=()=>{jump(options[+b.dataset.pvchoice].target);step()});return}case'ending':state.text=e.text;state.narrator=true;ended=true;ui(e.credits?'<button id="pvcredits">Титры</button><p>Конец истории</p>':'<p>Конец истории</p>');$('#pvcredits')?.addEventListener('click',()=>previewCards([{text:P.credits.title+'\n\n'+P.credits.lines,background:P.interface.background,seconds:P.credits.seconds}]));return;case'credits':previewCards([{text:P.credits.title+'\n\n'+P.credits.lines,background:P.interface.background,seconds:P.credits.seconds}],step);return;case'music':case'sound':if(e.type==='music'&&previewAudio)previewAudio.pause();{let audio=new Audio(assetURL(e.asset));audio.volume=Math.max(0,Math.min(1,Number(e.volume??1)));audio.loop=e.loop??e.type==='music';audio.play().catch(()=>toast('Браузер заблокировал звук'));if(e.type==='music'){previewAudio=audio}}break;case'stop_music':previewAudio?.pause();break;case'video':modal(`<div class="heading"><h2>Видео</h2><button data-close>Закрыть</button></div><video id="pvvideo" style="width:100%" controls autoplay src="${assetURL(e.asset)}"></video><button id="skipvideo">Продолжить</button>`);$('#pvvideo').onended=step;$('#skipvideo').onclick=step;return;case'cutscene':previewCards(P.cutscenes.find(c=>c.id===e.id)?.cards||[],step);return;case'minigame':testMini(P.minigames.find(g=>g.id===e.game),score=>{if(e.variable)vars[e.variable]=score;let g=P.minigames.find(g=>g.id===e.game),won=score>=g.target;if(g.rewardVariable)vars[g.rewardVariable]=(Number(vars[g.rewardVariable])||0)+Number(won?g.rewardWin:g.rewardLose);let target=won?g.winTarget:g.loseTarget;if(target)jump(target);step()});return;case'python':ui('<p class="warn">Python-модуль выполняется только в Ren’Py.</p><button id="skipplugin">Продолжить без вызова</button>');$('#skipplugin').onclick=step;return;case'achievement':toast('Достижение: '+e.id);break;case'pause':ui('<p>Пауза '+esc(e.value)+' сек.</p><button id="skippause">Продолжить</button>');$('#skippause').onclick=step;previewTimer=setTimeout(step,Math.max(0,Number(e.value))*1000);return;case'effect':break}}}catch(ex){toast(ex.message)}}step()}
function testMini(g,onDone){if(!g)return toast('Мини-игра не найдена');clearInterval(previewTimer);let score=0,elapsed=0,phase=0,player=.5,ball=.5,ballY=.08,finished=false;function done(){if(finished)return;finished=true;clearInterval(previewTimer);document.removeEventListener('keydown',key);if(onDone)onDone(score);else{closeModal();toast('Результат: '+score+' очков')}}let quiz=g.kind==='quiz';modal(`<div class="heading"><h2>${esc(g.title)}</h2><button data-close>Закрыть</button></div><p id="miniscore"></p>${quiz?`<h2 style="margin:20px 0">${esc(g.question)}</h2><div class="preview-options">${g.answers.map((a,i)=>`<button data-minianswer="${i}">${esc(a.text)}</button>`).join('')}</div>`:`<canvas id="minicanvas" width="900" height="340" style="width:100%;background:#143448;border-radius:10px;margin:15px 0"></canvas><div class="row">${g.kind==='volleyball'?'<button id="left">← Влево</button><button id="right">Вправо →</button>':'<button class="primary" id="hit">'+(g.kind==='timing'?'Попасть в зеленую зону':'Нажимайте!')+'</button>'}</div>`}<button id="finishmini" style="margin-top:15px">Завершить</button>`);$('#finishmini').onclick=done;$('#modal [data-close]').onclick=()=>{finished=true;document.removeEventListener('keydown',key);closeModal()};const move=d=>player=Math.max(.06,Math.min(.94,player+d));const hit=()=>{if(g.kind==='clicker'||g.kind==='timing'&&phase>=.36&&phase<=.64){score++;if(g.kind==='timing')phase=0}};function key(e){if(e.code==='ArrowLeft'){e.preventDefault();move(-.08)}if(e.code==='ArrowRight'){e.preventDefault();move(.08)}if(e.code==='Space'){e.preventDefault();hit()}}document.addEventListener('keydown',key);$('#hit')?.addEventListener('click',hit);$('#left')?.addEventListener('click',()=>move(-.08));$('#right')?.addEventListener('click',()=>move(.08));$$('[data-minianswer]').forEach(b=>b.onclick=()=>{score=g.answers[+b.dataset.minianswer].correct?1:0;done()});previewTimer=setInterval(()=>{if($('#modal').hidden){finished=true;clearInterval(previewTimer);document.removeEventListener('keydown',key);return}elapsed+=.05;phase=(phase+.025)%1;if(g.kind==='volleyball'){ballY+=.018;if(ballY>=.84){if(Math.abs(player-ball)<.15)score++;ballY=.08;ball=.06+Math.random()*.88}}$('#miniscore').textContent=`Очки: ${score} / ${g.target} · Осталось: ${Math.max(0,Math.ceil(g.seconds-elapsed))} сек.`;let canvas=$('#minicanvas');if(canvas){let c=canvas.getContext('2d');c.clearRect(0,0,900,340);if(g.kind==='volleyball'){c.fillStyle='#ffd875';c.beginPath();c.arc(ball*850,ballY*340,14,0,7);c.fill();c.fillStyle='#ad93ff';c.fillRect(player*850,300,80,15)}else if(g.kind==='timing'){c.fillStyle='#343249';c.fillRect(0,120,900,70);c.fillStyle='#4dcdb1';c.fillRect(324,120,252,70);c.fillStyle='white';c.fillRect(phase*880,120,10,70)}else{c.fillStyle='#b7a4ff';c.font='bold 90px sans-serif';c.textAlign='center';c.fillText(score,450,200)}}if((!quiz&&score>=g.target)||elapsed>=g.seconds)done()},50)}
window.addEventListener('beforeunload',e=>{if(dirty||saving){e.preventDefault();e.returnValue=''}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.code==='KeyS'){e.preventDefault();save().then(()=>toast('Сохранено')).catch(e=>toast(e.message))}if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();action(e.shiftKey?'redo':'undo')}if(e.key==='Escape')closeModal()});
